    @Column(name = "added_on", updatable = false)
    private LocalDate addedOn;

    /** The sheet's today when their retirement date was last set; null while not retired, or set before this was kept. */
    @Column(name = "retired_on")
    private LocalDate retiredOn;

    /** Their own terms in days, ahead of their grade's and the sheet's; null: none. */
    @Column(name = "terms")
    private Integer terms;

    /** Their contact, without surrounding spaces and lower-cased; null: none. */
    @Column(name = "contact")
    private String contact;

    @Column(name = "retired_from")
    private LocalDate retiredFrom;

    /** Their past retirements, earliest first. */
    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "person_retirement", joinColumns = @JoinColumn(name = "person_id"))
    public Map<LocalDate, String> getDatedGrades() { return new TreeMap<>(datedGrades); }

    /** Their own terms in days, or null when they have none. */
    public Integer getTerms() { return terms; }

    public void setTerms(Integer terms) { this.terms = terms; }

    /** Their contact, or null when they have none. */
    public String getContact() { return contact; }

    public void setContact(String contact) { this.contact = contactOf(contact); }

    /** A contact as it is stored: without surrounding spaces, lower-cased; blank or null: none. */
    public static String contactOf(String contact) {
        if (contact == null || contact.isBlank()) return null;
        return contact.strip().toLowerCase(Locale.ROOT);
    }

    /** Their aliases, sorted as names are compared (by key, then as given). */
    public List<String> getAliases() {
        return aliases.stream()
                .sorted(Comparator.comparing(PersonAlias::getAliasKey).thenComparing(PersonAlias::getAlias))
                .map(PersonAlias::getAlias).toList();
    }

    /** Whether they have the name, as names are compared, as an alias. */
    public boolean hasAlias(String name) {
        String key = keyOf(name);
        return aliases.stream().anyMatch(a -> a.getAliasKey().equals(key));
    }

    public void addAlias(String alias) { aliases.add(new PersonAlias(sheetId, alias)); }

    /**
     * Merge them into the other person: they name the other as merged into, and lose their aliases, holds
     * and contact. Returns their aliases, as given, in the order they were added.
     */
    public List<String> mergeInto(Long otherId) {
        List<String> theirs = aliases.stream().map(PersonAlias::getAlias).toList();
        this.mergedInto = otherId;
        this.liveNameKey = null;
        aliases.clear();
        holds.clear();
        this.contact = null;
        return theirs;
    }

    /** Move them to another sheet, noting the one they came from, with their grades, terms, contact, aliases and holds. */
    public void transferTo(String sheetId) {
        this.transferredFrom = this.sheetId;
        this.sheetId = sheetId;
        List<PersonAlias> theirs = new ArrayList<>(aliases);
        aliases.clear();
        for (PersonAlias a : theirs) aliases.add(new PersonAlias(sheetId, a.getAlias()));
    }

    /** The sheet they were last transferred from, or null when never transferred. */
    public String getTransferredFrom() { return transferredFrom; }

    /** Their name and aliases, as given. */
    public List<String> namesAndAliases() {
        List<String> all = new ArrayList<>();
        all.add(name);
        for (PersonAlias a : aliases) all.add(a.getAlias());
        return all;
    }

    /** The date they are retired from, or null while not retired. */
    public LocalDate getRetiredFrom() { return retiredFrom; }

    /** Retire them from the date, on the sheet's today. */
    }

    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        return add(sheetId, user, name, grade, null, null);
    }

    /** Add a person with their own terms in days (null: none) and contact (blank: none). */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade, Integer terms, String contact) {
        if (sheets.findForUpdate(sheetId).isEmpty()) throw new SheetNotFoundException();
        requireUnused(sheetId, name, null);
        requireUnusedInTree(sheetId, name);
        String key = Person.contactOf(contact);
        requireContactUnused(sheetId, key, null);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Person draft = new Person(sheetId, name, grade, today(sheetId));
        draft.setTerms(terms);
        draft.setContact(key);
        draft.setPosition(people.maxPosition(sheetId) + 1);
        Person person = saveUnique(draft);
        record("PERSON_ADDED", sheetId, user, person, person.getGrade(),
                (terms != null ? " terms=" + terms : "") + (key != null ? " contact=" + key : ""));
        rollup.recordChanges(sheetId, user, before);
        return person;
    }

    @Transactional
    public Person edit(String sheetId, String user, Long id, long version, String name, String grade,
            LocalDate gradeFrom, Integer terms, String contact) {
        Person person = people.findByIdAndSheetId(id, sheetId).orElseThrow(PersonNotFoundException::new);
        if (person.getVersion() != version) throw new PersonVersionConflictException();
        sheets.findForUpdate(sheetId).orElseThrow(SheetNotFoundException::new);
        requireUnused(sheetId, name, id);
        requireUnusedInTree(sheetId, name);
        for (String alias : person.getAliases()) requireUnusedInTree(sheetId, alias);
        String key = Person.contactOf(contact);
        requireContactUnused(sheetId, key, id);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate today = today(sheetId);
        person.setName(name);
        boolean termsChanged = !Objects.equals(terms, person.getTerms());
        person.setTerms(terms);
        boolean contactChanged = !Objects.equals(key, person.getContact());
        person.setContact(key);
        if (gradeFrom != null || !grade.equals(person.gradeOn(today))) {
            person.setGradeFrom(gradeFrom != null ? gradeFrom : today, grade, today);
        }
        Person saved = saveUnique(person);
        record("PERSON_EDITED", sheetId, user, saved, saved.gradeOn(today),
                (termsChanged ? " terms=" + (terms != null ? terms : "") : "")
                        + (contactChanged ? " contact=" + (key != null ? key : "") : ""));
        rollup.recordChanges(sheetId, user, before);
        return saved;
    }

    /**
     * Give each of the people the grade from the date (blank: the sheet's today), in list order, each as
     * its own edit would: name and terms kept, with its PERSON_EDITED and rollup lines, and no grade
     * recorded for one left on the grade in force today with the date blank. One not on the
     * sheet refuses them all. A viewer's, or one on an archived sheet, goes through with nothing done.

    /**
     * A person as the screen shows them: grade is the one in force on the sheet's today, grades every
     * grade recorded, earliest first (the first from null, the beginning of time); retiredFrom is null
     * while not retired; retirements their past ones, earliest first; held whether they have any hold, holds every hold, earliest first; patronIds
     * in the order named; watched whether the signed-in user watches them; terms their own, null for none;
     * contact theirs, null for none; aliases theirs, sorted as names are compared; active whether they are active on the sheet's today ({@link Person#activeOn});
     * clashing whether their name or an alias is used on another sheet of the sheet's tree ({@link PersonService#clashingIds});
     * origin the sheet they were transferred from, null when never transferred.
     */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
            boolean retired, LocalDate retiredFrom, boolean held, List<HoldView> holds, List<Long> patronIds,
            boolean watched, Integer terms, boolean active, String contact, List<String> aliases,
            boolean clashing, String origin, List<RetirementView> retirements) {
        public static PersonView of(Person person, LocalDate today, List<Long> patronIds, boolean watched,
                boolean active, boolean clashing) {
            List<GradeView> grades = new ArrayList<>();
            grades.add(new GradeView(null, person.getGrade()));
            person.getDatedGrades().forEach((from, grade) -> grades.add(new GradeView(from, grade)));
